import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"61、【中孚】 兌下巽上","description":"周易尚氏學 - 61、【中孚】 兌下巽上","frontmatter":{"title":"61、【中孚】 兌下巽上","description":"周易尚氏學 - 61、【中孚】 兌下巽上"},"headers":[],"relativePath":"classics/shangshi/066.md","filePath":"classics/shangshi/066.md"}'),s={name:"classics/shangshi/066.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_61、【中孚】-兌下巽上" tabindex="-1">61、【中孚】 兌下巽上 <a class="header-anchor" href="#_61、【中孚】-兌下巽上" aria-label="Permalink to “61、【中孚】 兌下巽上”">​</a></h1><p>上卦節。節信也。節何以為信。以中爻兩震竹相合。中孚初至五象與節同。仍兩竹相合。而在中四爻。故曰中孚。孚信也。歸藏曰大明。大明者離日晉順而麗乎大明是也。是以小過為坎。大明為離。取義與周易微異也。巽為豚為魚。魚象人知之。豚即失傳。豈知後初雲。贏豕孚滴（左足）躅。即以巽為豕。易林在有之後。牝豕無。假（左犬）旅之遁彭生為為豕。皆以巽為豕。蓋坎為豕以其隱伏。巽為伏。故亦為京。而中孚正覆巽。豚魚合居於中。故吉。坤為大川。震為舟為虛為木。五履重陰。乘震舟之上。故曰利涉大川。傳釋曰乘木舟虛。按渙傳雲。乘木有功。乘木即乘舟。又益傳雲。木道乃行。木亦謂舟。據王應麟所輯鄭注云。舟謂集板如今船。原作自。阮校詩穀風正義雲。自當為船。空大木為之曰虛。即古又名曰虛。總名皆曰舟。據鄭注木舟虛三者。平列為義。皆船也。利貞。傳釋為應乎天。五天位。三四皆陰爻。陽得陰則通。陰順陽故曰應乎天。</p><p>彖曰。中孚。柔在內而剛得中。說而巽。孚乃化邦也。豚魚吉。信及豚魚也。利涉大川。乘木舟虛也。中孚以利貞。乃應乎天也。</p><p>中爻艮為邦。艮邦震舟震象皆失傳。詳焦氏易詁。</p><p>象曰。澤上有風。中孚君子以議獄緩死。</p><p>玉篇獄謂之牢。又謂圜土。中爻艮止為獄。兩艮相合。則圜獄也。震為言故議獄。兌為毀折。故曰死。議獄緩死。欲孚及罪人而向善也。</p><p>初九。虞吉。有它不燕。</p><p>儀禮士虞禮注。釋虞為安。初陽遇陽不宜動。與節初同。節初九不出戶庭無咎。即謂安吉也。它謂四。四巽為隕落。有它謂不安於初。不顧二阻。而它往應四。則不燕也。燕與宴通。亦安也。兌為燕。四巽兌覆。故曰不燕。易林小畜之兌隨之革。皆曰燕雀銜茅。則皆以兌為燕。除易林外。他無用者。故易林為易象數（上草）。</p><h3 id="象曰。初九虞吉。志未變也。" tabindex="-1">象曰。初九虞吉。志未變也。 <a class="header-anchor" href="#象曰。初九虞吉。志未變也。" aria-label="Permalink to “象曰。初九虞吉。志未變也。”">​</a></h3><p>巽為志。志未變。言安於初而不應四。</p><p>九二。鳴鶴在陰。其子和之。我有好爵。吾與爾靡之。</p><p>震為鶴。為鳴。為子。陰山陰。二至五正反震。下震鶴。鳴于山陰。三至五震反。如聲回答。若相和然。故曰其子和之。其子謂覆震。非互震。判然二物也。易林大有之屯雲。嗟嗟所言。嗟嗟對語也。屯初至五亦正覆震相對。與中孚同。又同人之中孚雲。衣裳顛倒。震為衣。三至五震覆。故曰顛倒。渙之中孚雲。聞言不信。震言。三至五震覆。故不信。不信取其相反。子和取其相對。仍同也。而二至五亦正反艮。艮納丙為山陽。下二至四艮覆。則山陰矣。而二正當其處。故曰鳴鶴在陰。易林頤之中孚雲。熊羆豺狼。在山陰陽。正覆良故既曰熊羆。又曰豺狼。上艮為山陽。下覆艮為山陰也。故曰在山陰陽。易林釋此語。可謂明白矣。山陰之義。知者甚鮮。後獨茹敦和以陰為山陰。而取義於兌。兌者艮之反。艮山陽。兌山陰。義不本易林。而取義與易林同。故夫有清一代之易家。主張自己。不隨聲附和者。莫茹氏若也。爵。說文飲器。酒尊也。震為尊為爵為嘉。故曰好爵。正覆震相對。故曰吾與爾靡之。孟喜雲。靡共也。貞我悔彼。爾謂五。言二五共此爵也。</p><h3 id="象曰。其子和之。中心願也。" tabindex="-1">象曰。其子和之。中心願也。 <a class="header-anchor" href="#象曰。其子和之。中心願也。" aria-label="Permalink to “象曰。其子和之。中心願也。”">​</a></h3><p>巽為心志。鳴和全在中四爻。故曰中心願。</p><p>六三。得敵。或鼓或罷。或泣或歌。</p><p>子夏傳三與四為敵。故曰得敵。荀爽曰。三四俱陰。故稱敵也。中四爻艮相反覆。震為鼓。艮止故罷。罷疲通音婆。下與歌葉。諸家或作罷音非也。震為歌。震反則泣矣。與艮為山陽。艮反為山陰義同也。蓋三不當位而遇敵。故不常如此也。得敵與頤二之失類。艮之敵應。為易義之根本。所關甚大。乃得敵韓子夏與苟知之。失類則無知者。致陰遇陰陽遇陽之處皆失解。可喟也。</p><h3 id="象曰。或鼓或罷。位不當也。" tabindex="-1">象曰。或鼓或罷。位不當也。 <a class="header-anchor" href="#象曰。或鼓或罷。位不當也。" aria-label="Permalink to “象曰。或鼓或罷。位不當也。”">​</a></h3><p>義見前。</p><p>六四。月既望。馬匹亡。無咎。</p><p>兌為月。十五日日月望。乾象月盈甲。十六日平明。巽象月退辛。六四巽主。故曰既望。既王弼作幾。孟、荀皆作既。孟雲十六日也。作既於巽象方切。震為馬。四匹在初。馬匹亡。言不應初而承上也。承陽故無咎。</p><p>站長：孟、荀可能是指孟喜和荀爽，他們是西漢時期的易學家。應該當作「既望」，巽也為月始缺，如小畜「既雨既處...月既望」同理。</p><h3 id="象曰。馬匹亡。絕類上也。" tabindex="-1">象曰。馬匹亡。絕類上也。 <a class="header-anchor" href="#象曰。馬匹亡。絕類上也。" aria-label="Permalink to “象曰。馬匹亡。絕類上也。”">​</a></h3><p>陰陽相遇方為類。舊解皆以陰遇陰為類。故全易類宇皆失詁。絕者決也。言四遇三敵。不能應初。類上即承上也。</p><p>九五。有孚攣如。無咎。</p><p>五下乘重陰。得類。故曰有孚。言孚於二陰也。攣系也。戀也。前書李夫人傳。攣攣顧念我。有孚攣如者。言系攣三四也。五得位。故無咎。</p><h3 id="象曰。有孕攣如。位正當也" tabindex="-1">象曰。有孕攣如。位正當也 <a class="header-anchor" href="#象曰。有孕攣如。位正當也" aria-label="Permalink to “象曰。有孕攣如。位正當也”">​</a></h3><p>五既中且正。</p><p>上九。翰音登於天。貞兇。</p><p>曲禮曰。雞曰翰音。巽為雞。為高。居翼卜又居卦之極上。故曰翰音登於天。上應在三。三震為翰為音也。巽下隕。故貞兇。王注翰高飛也。飛音者。音飛而實不至之謂也。居卦之上。華美外揚。虛聲無實。故不可久長。</p><h3 id="象曰。翰青登於天。何可長也。" tabindex="-1">象曰。翰青登於天。何可長也。 <a class="header-anchor" href="#象曰。翰青登於天。何可長也。" aria-label="Permalink to “象曰。翰青登於天。何可長也。”">​</a></h3><p>窮上失位。下虛。故不長。翰音取象皆在應。非只巽雞。易無一字不由象生。觀此益信矣。震翰象失傳。詳焦氏易詁。</p>',31)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
